INSERT INTO `pages` VALUES (1,'{\"en\":\"About SmartTouch\",\"ar\":\"\\u0645\\u0646 \\u0646\\u062d\\u0646 - \\u0633\\u0645\\u0627\\u0631\\u062a \\u062a\\u0627\\u062a\\u0634\"}','{\"en\":\"about-us\",\"ar\":\"man-nahnu\"}','{\"en\":\"SmartTouch is a forward-thinking digital advertising and technology agency. We partner with trailblazing brands to build transformative web, mobile, and marketing experiences.\",\"ar\":\"\\u0633\\u0645\\u0627\\u0631\\u062a \\u062a\\u0627\\u062a\\u0634 \\u0647\\u064a \\u0648\\u0643\\u0627\\u0644\\u0629 \\u0631\\u0627\\u0626\\u062f\\u0629 \\u0641\\u064a \\u0645\\u062c\\u0627\\u0644 \\u0627\\u0644\\u062f\\u0639\\u0627\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0633\\u0648\\u064a\\u0642 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a \\u0648\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0627\\u0644\\u0648\\u064a\\u0628. \\u0646\\u062a\\u0634\\u0627\\u0631\\u0643 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0644\\u0627\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u064a\\u0629 \\u0627\\u0644\\u0637\\u0645\\u0648\\u062d\\u0629 \\u0644\\u0628\\u0646\\u0627\\u0621 \\u062a\\u062c\\u0627\\u0631\\u0628 \\u0631\\u0642\\u0645\\u064a\\u0629 \\u0648\\u062a\\u0633\\u0648\\u064a\\u0642\\u064a\\u0629 \\u0645\\u062a\\u0645\\u064a\\u0632\\u0629.\"}','about',1,'2026-09-05 21:51:01','2026-09-05 21:51:01'),(2,'{\"en\":\"Privacy Policy\",\"ar\":\"\\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629\"}','{\"en\":\"privacy-policy\",\"ar\":\"siyasat-al-khususiya\"}','{\"en\":\"At SmartTouch, we prioritize your data security and privacy. This policy outlines how we handle, store, and protect your information.\",\"ar\":\"\\u0641\\u064a \\u0633\\u0645\\u0627\\u0631\\u062a \\u062a\\u0627\\u062a\\u0634\\u060c \\u0646\\u0648\\u0644\\u064a \\u0633\\u0631\\u064a\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643\\u0645 \\u0623\\u0647\\u0645\\u064a\\u0629 \\u0642\\u0635\\u0648\\u0649. \\u062a\\u0648\\u0636\\u062d \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0648\\u062b\\u064a\\u0642\\u0629 \\u0633\\u064a\\u0627\\u0633\\u0627\\u062a \\u062c\\u0645\\u0639 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0648\\u062d\\u0645\\u0627\\u064a\\u062a\\u0647\\u0627.\"}','default',1,'2026-09-05 21:51:01','2026-09-05 21:51:01'),(3,'{\"en\":\"Terms of Service\",\"ar\":\"\\u0627\\u0644\\u0634\\u0631\\u0648\\u0637 \\u0648\\u0627\\u0644\\u0623\\u062d\\u0643\\u0627\\u0645\"}','{\"en\":\"terms-conditions\",\"ar\":\"al-shuroot-wal-ahkam\"}','{\"en\":\"Welcome to SmartTouch. By accessing our services, websites, or software solutions, you agree to our standard contractual terms.\",\"ar\":\"\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b \\u0628\\u0643\\u0645 \\u0641\\u064a \\u0633\\u0645\\u0627\\u0631\\u062a \\u062a\\u0627\\u062a\\u0634. \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0643\\u0645 \\u0644\\u062e\\u062f\\u0645\\u0627\\u062a\\u0646\\u0627 \\u0648\\u0645\\u0648\\u0627\\u0642\\u0639\\u0646\\u0627 \\u0623\\u0648 \\u062d\\u0644\\u0648\\u0644\\u0646\\u0627 \\u0627\\u0644\\u0628\\u0631\\u0645\\u062c\\u064a\\u0629\\u060c \\u0641\\u0625\\u0646\\u0643\\u0645 \\u062a\\u0648\\u0627\\u0641\\u0642\\u0648\\u0646 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0634\\u0631\\u0648\\u0637 \\u0648\\u0627\\u0644\\u0623\\u062d\\u0643\\u0627\\u0645 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0642\\u062f\\u064a\\u0629.\"}','default',1,'2026-09-05 21:51:01','2026-09-05 21:51:01');
