INSERT INTO `posts` VALUES (1,2,2,'{\"en\":\"Search Engine Dominance: Next-Gen SEO Strategies in 2026\",\"ar\":\"\\u0627\\u0644\\u0647\\u064a\\u0645\\u0646\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u062d\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u0628\\u062d\\u062b: \\u0627\\u0633\\u062a\\u0631\\u0627\\u062a\\u064a\\u062c\\u064a\\u0627\\u062a \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0627\\u0644\\u0633\\u064a\\u0648 \\u0641\\u064a 2026\"}','{\"en\":\"next-gen-seo-strategies-2026\",\"ar\":\"istratijiyat-al-seo-al-haditha-2026\"}','{\"en\":\"Explore how AI-driven search, semantic clustering, and Core Web Vitals dictate top rankings.\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0643\\u064a\\u0641 \\u064a\\u062a\\u062d\\u0643\\u0645 \\u0627\\u0644\\u0628\\u062d\\u062b \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0630\\u0643\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0635\\u0637\\u0646\\u0627\\u0639\\u064a \\u0648\\u0645\\u0624\\u0634\\u0631\\u0627\\u062a \\u0627\\u0644\\u0623\\u062f\\u0627\\u0621 \\u0641\\u064a \\u062a\\u0635\\u062f\\u0631 \\u0627\\u0644\\u0646\\u062a\\u0627\\u0626\\u062c \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649.\"}','{\"en\":\"Organic search has evolved beyond simple keyword densities. Search algorithms now inspect intent, user interaction momentum, and instant mobile responsiveness. In this article we outline actionable frameworks for achieving top visibility...\",\"ar\":\"\\u062a\\u0637\\u0648\\u0631 \\u0627\\u0644\\u0628\\u062d\\u062b \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a \\u0644\\u064a\\u062a\\u062c\\u0627\\u0648\\u0632 \\u0645\\u062c\\u0631\\u062f \\u062a\\u0643\\u0631\\u0627\\u0631 \\u0627\\u0644\\u0643\\u0644\\u0645\\u0627\\u062a \\u0627\\u0644\\u0645\\u0641\\u062a\\u0627\\u062d\\u064a\\u0629. \\u0623\\u0635\\u0628\\u062d\\u062a \\u062e\\u0648\\u0627\\u0631\\u0632\\u0645\\u064a\\u0627\\u062a \\u0627\\u0644\\u0628\\u062d\\u062b \\u062a\\u0631\\u0643\\u0632 \\u0639\\u0644\\u0649 \\u0646\\u064a\\u0629 \\u0627\\u0644\\u0628\\u0627\\u062d\\u062b \\u0648\\u0633\\u0644\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0639\\u0644 \\u0648\\u0633\\u0631\\u0639\\u0629 \\u0627\\u0644\\u0623\\u062f\\u0627\\u0621 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062c\\u0648\\u0627\\u0644. \\u0646\\u0633\\u062a\\u0639\\u0631\\u0636 \\u0647\\u0646\\u0627 \\u0623\\u0647\\u0645 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0631\\u0627\\u062a\\u064a\\u062c\\u064a\\u0627\\u062a \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0644\\u062a\\u0635\\u062f\\u0631 \\u0646\\u062a\\u0627\\u0626\\u062c \\u0627\\u0644\\u0628\\u062d\\u062b...\"}',NULL,'published','2026-09-05 22:19:20','2026-09-05 21:51:01','2026-09-05 22:19:20'),(2,2,1,'{\"en\":\"Why Fast Next.js & Laravel Stacks Are Dominating Enterprise Web\",\"ar\":\"\\u0644\\u0645\\u0627\\u0630\\u0627 \\u062a\\u062a\\u0635\\u062f\\u0631 \\u0645\\u0646\\u0638\\u0648\\u0645\\u0629 Next.js \\u0648 Laravel \\u062a\\u0637\\u0648\\u064a\\u0631 \\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u0643\\u0628\\u0631\\u0649\"}','{\"en\":\"nextjs-laravel-enterprise-stack\",\"ar\":\"nextjs-laravel-lil-sharikat\"}','{\"en\":\"Combining modern headless frontend rendering with a battle-tested Laravel 12 API backend.\",\"ar\":\"\\u0627\\u0644\\u062c\\u0645\\u0639 \\u0628\\u064a\\u0646 \\u0648\\u0627\\u062c\\u0647\\u0627\\u062a Next.js \\u0627\\u0644\\u0645\\u062a\\u0637\\u0648\\u0631\\u0629 \\u0648\\u0633\\u0631\\u0639\\u0629 \\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u062a\\u0647\\u0627 \\u0645\\u0639 \\u0642\\u0648\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0648\\u0627\\u062c\\u0647\\u0627\\u062a \\u0628\\u0631\\u0645\\u062c\\u0629 \\u062a\\u0637\\u0628\\u064a\\u0642\\u0627\\u062a Laravel 12.\"}','{\"en\":\"Modern digital experiences demand fluid 60fps animations, zero-lag transitions, and rock-solid relational data integrity. Coupling Next.js App Router with Laravel 12 provides the ultimate synergy for speed, security, and developer joy...\",\"ar\":\"\\u062a\\u062a\\u0637\\u0644\\u0628 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0628 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062d\\u062f\\u064a\\u062b\\u0629 \\u062d\\u0631\\u0643\\u0627\\u062a \\u0627\\u0646\\u0633\\u064a\\u0627\\u0628\\u064a\\u0629 \\u0641\\u0627\\u0626\\u0642\\u0629 \\u0648\\u0633\\u0631\\u0639\\u0629 \\u0627\\u0646\\u062a\\u0642\\u0627\\u0644 \\u0633\\u0644\\u0633\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u062b\\u0648\\u0642\\u064a\\u0629 \\u0648\\u0623\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a. \\u064a\\u0634\\u0643\\u0644 \\u062f\\u0645\\u062c Next.js \\u0645\\u0639 Laravel 12 \\u0627\\u0644\\u062d\\u0644 \\u0627\\u0644\\u0623\\u0645\\u062b\\u0644 \\u0644\\u062a\\u062d\\u0642\\u064a\\u0642 \\u0627\\u0644\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0627\\u0644\\u0623\\u0645\\u0627\\u0646...\"}',NULL,'published','2026-09-05 22:19:20','2026-09-05 21:51:01','2026-09-05 22:19:20'),(3,2,1,'{\"en\":\"The Latest Innovation in Web 2026\",\"ar\":\"\\u0623\\u062d\\u062f\\u062b \\u0627\\u0644\\u0627\\u0628\\u062a\\u0643\\u0627\\u0631\\u0627\\u062a \\u0641\\u064a \\u0639\\u0627\\u0644\\u0645 \\u0627\\u0644\\u0648\\u064a\\u0628 2026\"}','{\"en\":\"the-latest-innovation-in-web-2026\",\"ar\":\"the-latest-innovation-in-web-2026\"}','{\"en\":\"Discover the breakthrough technologies reshaping web development in 2026: AI rendering engines, edge orchestration, and fluid fluid interaction design.\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0623\\u062d\\u062f\\u062b \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u062b\\u0648\\u0631\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0639\\u064a\\u062f \\u0635\\u064a\\u0627\\u063a\\u0629 \\u062a\\u0637\\u0648\\u064a\\u0631 \\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u0648\\u064a\\u0628 \\u0641\\u064a 2026: \\u0645\\u062d\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0630\\u0643\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u062a\\u0641\\u0627\\u0639\\u0644 \\u0627\\u0644\\u0627\\u0646\\u0633\\u064a\\u0627\\u0628\\u064a \\u0641\\u0627\\u0626\\u0642 \\u0627\\u0644\\u0633\\u0631\\u0639\\u0629.\"}','{\"en\":\"The web in 2026 is defined by instantaneous responsiveness, generative user experiences, and seamless headless synchronization. In this deep dive, our technical directors dissect how cutting-edge stacks combining Next.js 16 and Laravel 12 are powering the next generation of scalable web applications.\",\"ar\":\"\\u064a\\u0634\\u0647\\u062f \\u0639\\u0627\\u0644\\u0645 \\u0627\\u0644\\u0648\\u064a\\u0628 \\u0641\\u064a 2026 \\u062b\\u0648\\u0631\\u0629 \\u062d\\u0642\\u064a\\u0642\\u064a\\u0629 \\u0641\\u064a \\u0633\\u0631\\u0639\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0644\\u062d\\u0638\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0628 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0644\\u062f\\u0629 \\u0628\\u0627\\u0644\\u0630\\u0643\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0635\\u0637\\u0646\\u0627\\u0639\\u064a. \\u064a\\u0633\\u062a\\u0639\\u0631\\u0636 \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0627\\u0644\\u0641\\u0646\\u064a \\u0643\\u064a\\u0641 \\u062a\\u0636\\u0639 \\u0628\\u0646\\u064a\\u0627\\u062a Next.js \\u0648 Laravel 12 \\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u062a\\u0645\\u0627\\u0645\\u0627\\u064b \\u0644\\u0643\\u0628\\u0631\\u0649 \\u0627\\u0644\\u0645\\u0624\\u0633\\u0633\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629.\"}',NULL,'published','2026-09-05 22:19:20','2026-09-05 22:19:20','2026-09-05 22:19:20');
