INSERT INTO `seo_metadata` VALUES (1,'portfolio',1,'{\"en\":\"5D Investment Holding Co. Ltd. | Portfolio | Smart Touch\",\"ar\":\"\\u0634\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0628\\u0639\\u062f \\u0627\\u0644\\u062e\\u0627\\u0645\\u0633 \\u0627\\u0644\\u0642\\u0627\\u0628\\u0636\\u0629 \\u0644\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 | \\u0633\\u0627\\u0628\\u0642\\u0629 \\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 | \\u0633\\u0645\\u0627\\u0631\\u062a \\u062a\\u0627\\u062a\\u0634\"}','{\"en\":\"Fifth Dimension Investment Holding Co. Ltd is a holding company which provides professional services in real estate and industrial investment.\",\"ar\":\"\\u0634\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0628\\u0639\\u062f \\u0627\\u0644\\u062e\\u0627\\u0645\\u0633 \\u0627\\u0644\\u0642\\u0627\\u0628\\u0636\\u0629 \\u0644\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u0623\\u0648 \\u0627\\u0644\\u0628\\u0639\\u062f \\u0627\\u0644\\u062e\\u0627\\u0645\\u0633, \\u0647\\u064a \\u0634\\u0631\\u0643\\u0629 \\u0642\\u0627\\u0628\\u0636\\u0629 \\u062a\\u0648\\u0641\\u0631 \\u062e\\u062f\\u0645\\u0627\\u062a \\u0645\\u0647\\u0646\\u064a\\u0629 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0648 \\u0627\\u0644\\u0625\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u064a\"}','{\"en\":\"5D Investment Holding Co. Ltd. | Portfolio | Smart Touch\",\"ar\":\"\\u0634\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0628\\u0639\\u062f \\u0627\\u0644\\u062e\\u0627\\u0645\\u0633 \\u0627\\u0644\\u0642\\u0627\\u0628\\u0636\\u0629 \\u0644\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 | \\u0633\\u0627\\u0628\\u0642\\u0629 \\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 | \\u0633\\u0645\\u0627\\u0631\\u062a \\u062a\\u0627\\u062a\\u0634\"}','{\"en\":\"Fifth Dimension Investment Holding Co. Ltd is a holding company which provides professional services in real estat